CREATE VIEW kicad_diode AS SELECT v.*, v."Sim.Library" AS sim_library, v."Sim.Name" AS sim_name, v."Sim.Pins" AS sim_pins, v."Sim.Params" AS sim_params, v."Sim.Device" AS sim_device, v."Sim.Type" AS sim_type FROM (SELECT c.id,c.mpn,m.name AS manufacturer,c.description,e.kicad_symbol AS symbol,e.kicad_footprint AS footprint,e.kicad_3d_model AS "3d_model",d.vr_max,d.if_avg,d.vf_typ,d.aec_q101,s.status AS simulation_status,s.model_name AS simulation_model,s.model_file AS "Sim.Library",s.model_name AS "Sim.Name",(SELECT group_concat(pair,' ') FROM (SELECT p.symbol_pin || '=' || p.model_pin AS pair FROM simulation_pin_map p WHERE p.simulation_model_id=s.id ORDER BY p.model_pin)) AS "Sim.Pins",'' AS "Sim.Params",NULL AS "Sim.Device",NULL AS "Sim.Type" FROM components c JOIN categories cat ON cat.id=c.category_id LEFT JOIN manufacturers m ON m.id=c.manufacturer_id LEFT JOIN eda_mapping e ON e.component_id=c.id LEFT JOIN preferred_models pref ON pref.component_id=c.id AND pref.purpose='dc' LEFT JOIN simulation_models s ON s.id=pref.simulation_model_id AND s.component_id=c.id AND s.status='VERIFIED' AND s.simulator='ngspice' AND s.compatibility='NATIVE_NGSPICE' LEFT JOIN spec_diode d ON d.component_id=c.id WHERE cat.path LIKE 'semiconductor/diode/%') v;
CREATE VIEW kicad_mosfet AS SELECT v.*, v."Sim.Library" AS sim_library, v."Sim.Name" AS sim_name, v."Sim.Pins" AS sim_pins, v."Sim.Params" AS sim_params, v."Sim.Device" AS sim_device, v."Sim.Type" AS sim_type FROM (SELECT c.id,c.mpn,m.name AS manufacturer,c.description,e.kicad_symbol AS symbol,e.kicad_footprint AS footprint,e.kicad_3d_model AS "3d_model",d.vds_max,d.id_cont,d.rds_on,d.qg,d.aec_q101,s.status AS simulation_status,s.model_name AS simulation_model,s.model_file AS "Sim.Library",s.model_name AS "Sim.Name",(SELECT group_concat(pair,' ') FROM (SELECT p.symbol_pin || '=' || p.model_pin AS pair FROM simulation_pin_map p WHERE p.simulation_model_id=s.id ORDER BY p.model_pin)) AS "Sim.Pins",'' AS "Sim.Params",NULL AS "Sim.Device",NULL AS "Sim.Type" FROM components c JOIN categories cat ON cat.id=c.category_id LEFT JOIN manufacturers m ON m.id=c.manufacturer_id LEFT JOIN eda_mapping e ON e.component_id=c.id LEFT JOIN preferred_models pref ON pref.component_id=c.id AND pref.purpose='dc' LEFT JOIN simulation_models s ON s.id=pref.simulation_model_id AND s.component_id=c.id AND s.status='VERIFIED' AND s.simulator='ngspice' AND s.compatibility='NATIVE_NGSPICE' LEFT JOIN spec_mosfet d ON d.component_id=c.id WHERE cat.path LIKE 'semiconductor/transistor/mosfet/%') v;
CREATE VIEW kicad_bjt AS SELECT v.*, v."Sim.Library" AS sim_library, v."Sim.Name" AS sim_name, v."Sim.Pins" AS sim_pins, v."Sim.Params" AS sim_params, v."Sim.Device" AS sim_device, v."Sim.Type" AS sim_type FROM (SELECT c.id,c.mpn,m.name AS manufacturer,c.description,e.kicad_symbol AS symbol,e.kicad_footprint AS footprint,e.kicad_3d_model AS "3d_model",s.status AS simulation_status,s.model_name AS simulation_model,s.model_file AS "Sim.Library",s.model_name AS "Sim.Name",(SELECT group_concat(pair,' ') FROM (SELECT p.symbol_pin || '=' || p.model_pin AS pair FROM simulation_pin_map p WHERE p.simulation_model_id=s.id ORDER BY p.model_pin)) AS "Sim.Pins",'' AS "Sim.Params",NULL AS "Sim.Device",NULL AS "Sim.Type" FROM components c JOIN categories cat ON cat.id=c.category_id LEFT JOIN manufacturers m ON m.id=c.manufacturer_id LEFT JOIN eda_mapping e ON e.component_id=c.id LEFT JOIN preferred_models pref ON pref.component_id=c.id AND pref.purpose='dc' LEFT JOIN simulation_models s ON s.id=pref.simulation_model_id AND s.component_id=c.id AND s.status='VERIFIED' AND s.simulator='ngspice' AND s.compatibility='NATIVE_NGSPICE'  WHERE cat.path LIKE 'semiconductor/transistor/bjt/%') v;
CREATE VIEW kicad_passive AS SELECT v.*, v."Sim.Library" AS sim_library, v."Sim.Name" AS sim_name, v."Sim.Pins" AS sim_pins, v."Sim.Params" AS sim_params, v."Sim.Device" AS sim_device, v."Sim.Type" AS sim_type FROM (SELECT c.id,c.mpn,m.name AS manufacturer,c.description,e.kicad_symbol AS symbol,e.kicad_footprint AS footprint,e.kicad_3d_model AS "3d_model",'INTRINSIC' AS simulation_status,NULL AS simulation_model,NULL AS "Sim.Library",NULL AS "Sim.Name",'1=1 2=2' AS "Sim.Pins",CASE cat.path WHEN 'passive/resistor' THEN 'r=' WHEN 'passive/capacitor' THEN 'c=' ELSE 'l=' END || CAST(p.value_si AS TEXT) AS "Sim.Params",CASE cat.path WHEN 'passive/resistor' THEN 'R' WHEN 'passive/capacitor' THEN 'C' ELSE 'L' END AS "Sim.Device",CASE cat.path WHEN 'passive/resistor' THEN 'R' WHEN 'passive/capacitor' THEN 'C' ELSE 'L' END AS "Sim.Type" FROM components c JOIN categories cat ON cat.id=c.category_id JOIN eda_mapping e ON e.component_id=c.id LEFT JOIN manufacturers m ON m.id=c.manufacturer_id JOIN parameters p ON p.component_id=c.id JOIN parameter_definitions pd ON pd.id=p.definition_id WHERE c.generic=1 AND ((cat.path='passive/resistor' AND pd.name='resistance') OR (cat.path='passive/capacitor' AND pd.name='capacitance') OR (cat.path='passive/inductor' AND pd.name='inductance'))) v;
